#include <memory>
#include <utility>
#include <vector>

struct Shape {
  virtual ~Shape() = default;
  virtual double area() const = 0;
  virtual std::unique_ptr<Shape> clone() const = 0;
protected:  // prevent slicing copies through Shape
  Shape() = default;
  Shape(const Shape&) = default;
  Shape& operator=(const Shape&) = default;
};

template <class D>
struct Cloneable : Shape {  // CRTP: one clone implementation
  std::unique_ptr<Shape> clone() const override {
    return std::make_unique<D>(static_cast<const D&>(*this));
  }
};

struct Circle final : Cloneable<Circle> {
  double r;
  explicit Circle(double r) : r(r) {}
  double area() const override { return 3.141592653589793 * r * r; }
};

class Drawing {
  std::vector<std::unique_ptr<Shape>> shapes_;
public:
  Drawing() = default;
  Drawing(const Drawing& o) {
    shapes_.reserve(o.shapes_.size());
    for (const auto& s : o.shapes_) shapes_.push_back(s->clone());
  }
  Drawing& operator=(const Drawing& o) {
    Drawing tmp(o);              // strong guarantee
    shapes_.swap(tmp.shapes_);
    return *this;
  }
  Drawing(Drawing&&) noexcept = default;
  Drawing& operator=(Drawing&&) noexcept = default;
  void add(std::unique_ptr<Shape> s) { shapes_.push_back(std::move(s)); }
};

