struct ShapeOps;
struct Shape { const ShapeOps* ops; };
double total_area(Shape* const* shapes, int n);

questions.modelAnswer:
struct Shape;
struct ShapeOps {
  double (*area)(const Shape*);
  const char* (*name)(const Shape*);
};
struct Shape { const ShapeOps* ops; };

struct Circle { Shape base; double r; };   // base must be first
struct Rect   { Shape base; double w, h; };

static double circle_area(const Shape* s) {
  auto* c = reinterpret_cast<const Circle*>(s);  // OK: base is first member, standard-layout
  return 3.14159265358979 * c->r * c->r;
}
static const char* circle_name(const Shape*) { return "circle"; }
static double rect_area(const Shape* s) {
  auto* r = reinterpret_cast<const Rect*>(s);
  return r->w * r->h;
}
static const char* rect_name(const Shape*) { return "rect"; }

static const ShapeOps kCircleOps{circle_area, circle_name};  // one table per type
static const ShapeOps kRectOps{rect_area, rect_name};

Circle make_circle(double r) { return Circle{{&kCircleOps}, r}; }
Rect make_rect(double w, double h) { return Rect{{&kRectOps}, w, h}; }

double total_area(Shape* const* shapes, int n) {
  double sum = 0;
  for (int i = 0; i < n; ++i)
    sum += shapes[i]->ops->area(shapes[i]);   // load table, load slot, indirect call
  return sum;
}

